solutionReferences.cpp:
#include <iostream>

class Rectangulo {
public:
    double base;
    double altura;

    Rectangulo(double b, double h) {
        base = b;
        altura = h;
    }

    void describir() const {
        std::cout << "Rectángulo de " << (int)base << "x" << (int)altura << "\n";
    }

    double calcularArea() const {
        return base * altura;
    }
};

int main() {
    Rectangulo r(5, 3);
    r.describir();
    std::cout << r.calcularArea() << "\n";
    return 0;
}
